window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[286]={"id":"286","numero":286,"titre":"Diarrhée aiguë chez l'enfant et l'adulte","objectifs":[{"id":"286-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une diarrhée aiguë","contenu":"<p>Une <span class=\"kw-def\">diarrhée aiguë</span> est une <span class=\"kw-clinique\">diarrhée</span> qui <strong>évolue depuis <span class=\"kw-chiffre\">moins de 2 semaines</span></strong>.</p>\n      <p>Elle se distingue ainsi de la forme <span class=\"kw-def\">prolongée</span> (<span class=\"kw-chiffre\">2 à 4 semaines</span>) et de la forme <span class=\"kw-def\">chronique</span> (<span class=\"kw-chiffre\">&gt; 1 mois</span>). La définition de la <span class=\"kw-clinique\">diarrhée</span> elle-même (<span class=\"kw-chiffre\">≥ 3 selles</span> très molles à liquides par jour ou poids <span class=\"kw-chiffre\">&gt; 250-300 g/24 h</span>) est rappelée dans l’objectif « Connaître la définition d’une <span class=\"kw-clinique\">diarrhée</span> ».</p>","frequence":0},{"id":"286-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome dysentérique","contenu":"<p>Le <span class=\"kw-def\">syndrome dysentérique</span> associe des selles <span class=\"kw-clinique\">afécales</span>, <span class=\"kw-clinique\">glaireuses</span> et <span class=\"kw-clinique\">sanglantes</span> (parfois mucopurulentes), des <span class=\"kw-clinique\">douleurs abdominales</span>, et un <strong>syndrome rectal</strong>. Il témoigne d’un mécanisme <span class=\"kw-def\">entéro-invasif</span> avec atteinte de la muqueuse colique ou iléo-colique.</p>\n      <table >\n        <thead><tr><th>Composante du syndrome rectal</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Épreinte</span></td><td>Douleurs coliques / pelviennes avec spasme rectal, <strong>soulagées par l’émission de selles</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ténesme</span></td><td>Tension douloureuse de la région anale, <strong>persistant après l’exonération</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Faux besoins</span></td><td>Fausse envie impérieuse d’aller à la selle</td></tr>\n        </tbody>\n      </table>\n      <p>L’émission de selles <span class=\"kw-clinique\">glairo-sanglantes</span> est en faveur d’une <strong>rectite</strong> — atteinte colique distale, le sang n’ayant pas le temps d’être digéré.</p>","frequence":0},{"id":"286-3","rang":"A","rubrique":"Épidémiologie","titre":"Connaître l’incidence et la prévalence des diarrhées aiguës","contenu":"<p>La <span class=\"kw-clinique\">diarrhée</span> aiguë est extrêmement fréquente :</p>\n      <ul>\n        <li>Environ <span class=\"kw-chiffre\">1 épisode digestif aigu par an</span> et par habitant (<span class=\"kw-clinique\">vomissements</span> ou <span class=\"kw-clinique\">diarrhée</span>) — ces épisodes durent généralement <span class=\"kw-chiffre\">&lt; 24 h</span> et ne donnent pas lieu à consultation (souvent d’origine alimentaire).</li>\n        <li>Chaque année en France, <span class=\"kw-chiffre\">5 %</span> des habitants consultent pour une <span class=\"kw-clinique\">diarrhée</span> évoluant <span class=\"kw-chiffre\">&gt; 24 h</span>.</li>\n      </ul>","frequence":0},{"id":"286-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","contenu":"<p>L’interrogatoire et l’examen clinique permettent de rattacher la <span class=\"kw-clinique\">diarrhée</span> à son <span class=\"kw-def\">mécanisme</span> — invasif ou sécrétoire — qui oriente toute la prise en charge.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Mécanisme invasif</th><th>Mécanisme sécrétoire</th></tr></thead>\n        <tbody>\n          <tr><td>Selles</td><td><span class=\"kw-clinique\">Glairo-sanglantes, afécales</span></td><td><span class=\"kw-clinique\">Hydriques, aqueuses</span> (« eau de riz »)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span></td><td><span class=\"kw-clinique\">Présente</span> (infection invasive)</td><td><span class=\"kw-clinique\">Absente</span> habituellement</td></tr>\n          <tr><td>Syndrome rectal</td><td>Épreintes, ténesme, faux besoins</td><td>Absent</td></tr>\n          <tr><td>Siège</td><td>Côlon</td><td>Intestin grêle</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interrogatoire — contexte à rechercher</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Voyage récent</span> — infection tropicale, parasitose</li>\n        <li><span class=\"kw-clinique\">Antibiothérapie &lt; 3 mois</span> — suspicion de <span class=\"kw-etio\">C. difficile</span></li>\n        <li><span class=\"kw-clinique\">Cas groupés</span> (familial, restauration collective) — suspicion de TIAC</li>\n        <li><span class=\"kw-clinique\">Contage</span>, contexte épidémique</li>\n      </ul>\n      <p><strong>Examen clinique — à apprécier</strong> : <span class=\"kw-alerte\">signes de gravité</span> (<span class=\"kw-def\">sepsis</span>), <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-alerte\">défense abdominale</span> (complication : perforation), arrêt des matières et des gaz (occlusion).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":3},{"id":"286-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","contenu":"<p>Une modification du transit survient chez <span class=\"kw-chiffre\">&gt; 10 %</span> des patients recevant des antibiotiques. Par définition, une <span class=\"kw-clinique\">diarrhée</span> survenant <strong>pendant un traitement antibiotique ou dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 mois</span> suivant son arrêt</strong> est une « <span class=\"kw-clinique\">diarrhée</span> des antibiotiques ».</p>\n      <p><strong>Deux mécanismes</strong> :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Effet pharmacologique sur la motricité — <strong>rare</strong></td><td>ATB en cause : <span class=\"kw-ttt\">érythromycine</span>, <span class=\"kw-ttt\">acide clavulanique</span> ; la <span class=\"kw-clinique\">diarrhée</span> apparaît rapidement à l’introduction et cesse à l’arrêt</td></tr>\n          <tr><td>Modification de la flore intestinale — <strong>fréquent</strong></td><td><span class=\"kw-etio\">Dysbiose</span> ; aboutit aux deux catégories ci-dessous</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Les</span> deux catégories de la <span class=\"kw-clinique\">diarrhée</span> des antibiotiques</strong> :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Diarrhée</span> bénigne fonctionnelle</th><th>Colite infectieuse</th></tr></thead>\n        <tbody>\n          <tr><td>Fréquence</td><td><strong>Fréquente</strong> — présentation la plus courante</td><td><strong>Rare</strong></td></tr>\n          <tr><td>Mécanisme</td><td><span class=\"kw-etio\">Dysbiose</span> : baisse de la fermentation des sucres par le microbiote colique</td><td><span class=\"kw-etio\">C. difficile</span> ; <span class=\"kw-etio\">Klebsiella oxytoca</span></td></tr>\n          <tr><td>Délai</td><td><span class=\"kw-chiffre\">4 à 6 jours</span> après le début du traitement</td><td>Quelques jours après la prise (K. oxytoca)</td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Pas de fièvre</span> ; transitoire</td><td>K. oxytoca : <span class=\"kw-clinique\">diarrhée hémorragique</span>, lésions segmentaires, aspect <span class=\"kw-etio\">ischémique</span></td></tr>\n          <tr><td>Exploration</td><td><strong>Aucune</strong></td><td><span class=\"kw-bio\">Coproculture</span> orientée ; recherche de toxines de <span class=\"kw-etio\">C. difficile</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Cède rapidement à l’arrêt de l’ATB</td><td>Voir l’objectif « traitement de la <span class=\"kw-clinique\">diarrhée</span> et des colites des antibiotiques »</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 177 — Anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"286-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de la diarrhée aiguë nosocomiale","contenu":"<p>Une <span class=\"kw-def\">diarrhée aiguë nosocomiale</span> est, par définition, une <span class=\"kw-clinique\">diarrhée</span> survenant <strong>&gt;<span class=\"kw-chiffre\"> 3 jours</span> après l’admission</strong> du patient en milieu hospitalier.</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Facteurs de risque</span></strong> — <span class=\"kw-ttt\">antibiothérapie</span>, âge, présence d’un voisin de chambre, durée de séjour</li>\n        <li><strong>Germes en cause</strong> — <span class=\"kw-etio\">Clostridioides difficile</span> +++ (1ʳᵉ cause de <span class=\"kw-clinique\">diarrhée</span> nosocomiale chez l’adulte), puis <span class=\"kw-etio\">salmonelles</span>, <span class=\"kw-etio\">virus</span>, certains parasites (<span class=\"kw-etio\">Giardia intestinalis</span>)</li>\n        <li><strong>Conduite à tenir</strong> — <span class=\"kw-bio\">coproculture</span>, <span class=\"kw-bio\">examen parasitologique des selles</span>, <span class=\"kw-bio\">recherche de C. difficile et de ses toxines</span></li>\n      </ul>","frequence":0},{"id":"286-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires","contenu":"<p><span class=\"kw-clinique\">Les</span> explorations complémentaires devant une <span class=\"kw-clinique\">diarrhée</span> aiguë ne sont nécessaires que si <strong><span class=\"kw-chiffre\">≥ 1</span> signe</strong> est présent parmi :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Sujet âgé ; valvulopathie ; <span class=\"kw-etio\">immunodépression</span></td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">&gt; 3 jours</span> ; <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 38,5 °C</span> ; <span class=\"kw-clinique\">syndrome dysentérique</span> (sang ou pus dans <span class=\"kw-clinique\">les</span> selles) ; <span class=\"kw-clinique\">déshydratation</span></td></tr>\n          <tr><td>Contexte</td><td>Contexte épidémique nosocomial ; <span class=\"kw-clinique\">diarrhée</span> post-antibiotique (sauf forme bénigne) ; suspicion de TIAC</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Aucune exploration n’est nécessaire devant une <span class=\"kw-clinique\">diarrhée aiguë banale</span>, sans <span class=\"kw-clinique\">fièvre</span>, sans <span class=\"kw-alerte\">signe de gravité</span>, évoluant rapidement vers la guérison — la majorité des cas.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/clostridioides-difficile-colitis","label":"Radiopaedia : Clostridioides difficile colitis"}]},{"id":"286-8","rang":"A","rubrique":"Étiologie","titre":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","contenu":"<p>Six germes sont à connaître dans <span class=\"kw-clinique\">les</span> intoxications alimentaires. Ils se répartissent selon leur mécanisme :</p>\n      <table >\n        <thead><tr><th>Germe</th><th>Mécanisme</th><th>Syndrome</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Staphylocoque doré</span> (S. aureus)</td><td><span class=\"kw-def\">Toxinogène</span> — toxine pré-formée dans l’aliment</td><td>Cholériforme</td></tr>\n          <tr><td><span class=\"kw-etio\">Clostridium perfringens</span></td><td><span class=\"kw-def\">Toxinogène</span></td><td>Cholériforme</td></tr>\n          <tr><td><span class=\"kw-etio\">Salmonella</span> (non Typhi)</td><td><span class=\"kw-def\">Entéro-invasif</span></td><td>Gastro-entéritique</td></tr>\n          <tr><td><span class=\"kw-etio\">Campylobacter</span></td><td><span class=\"kw-def\">Entéro-invasif</span></td><td>Gastro-entéritique</td></tr>\n          <tr><td><span class=\"kw-etio\">Escherichia coli</span></td><td>Variable selon le type — entéro-toxinogène, entéro-pathogène, entéro-invasif ou entéro-<span class=\"kw-etio\">hémorragique</span></td><td>Cholériforme, gastro-entéritique ou dysentérique</td></tr>\n          <tr><td><span class=\"kw-etio\">Yersinia</span></td><td><span class=\"kw-def\">Entéro-invasif</span></td><td>Gastro-entéritique</td></tr>\n        </tbody>\n      </table>\n      <p>Schématiquement : germes <strong>toxinogènes</strong> → tableau sécrétoire / cholériforme ; germes <strong>entéro-invasifs</strong> → tableau gastro-entéritique ou dysentérique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":1},{"id":"286-9","rang":"A","rubrique":"Suivi et/ou Pronostic","titre":"Connaître la complication majeure : la déshydratation globale (et ses conséquences)","contenu":"<p>La complication majeure de la <span class=\"kw-clinique\">diarrhée</span> aiguë est la <span class=\"kw-alerte\">déshydratation globale</span> — touchant <span class=\"kw-clinique\">les</span> deux compartiments. Les diarrhées entraînent des pertes d’<span class=\"kw-bio\">eau</span>, de <span class=\"kw-bio\">sodium</span>, de <span class=\"kw-bio\">potassium</span> et de <span class=\"kw-bio\">bicarbonates</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Déshydratation</span> intracellulaire</th><th><span class=\"kw-clinique\">Déshydratation</span> extracellulaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Soif</span></td><td><span class=\"kw-alerte\">Tachycardie, hypotension, oligurie</span> (<span class=\"kw-alerte\">signes de gravité</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Sécheresse des muqueuses</span></td><td><span class=\"kw-clinique\">Pli cutané persistant</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre, troubles de conscience</span></td><td><span class=\"kw-clinique\">Cernes, yeux creusés</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> Chez le sujet de <span class=\"kw-alerte\">&gt; 75 ans</span>, la <span class=\"kw-def\">mortalité</span> tient aux accidents de <span class=\"kw-clinique\">déshydratation</span> et à l’<span class=\"kw-alerte\">hypoperfusion des organes vitaux</span> — avec un pic de mortalité <span class=\"kw-chiffre\">8 à 10 jours</span> après le début de la <span class=\"kw-clinique\">diarrhée</span>, alors que celle-ci a souvent déjà disparu.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-def\">Insuffisance rénale aiguë</span> - <span class=\"kw-clinique\">anurie</span></em></p>","frequence":0},{"id":"286-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","contenu":"<div class=\"callout callout-info\"><strong>Principe directeur.</strong> <span class=\"kw-clinique\">Diarrhée</span> <strong>sécrétoire</strong> : traitement dominé par la <span class=\"kw-ttt\">réhydratation hydroélectrolytique</span>. <span class=\"kw-clinique\">Diarrhée</span> <strong>invasive</strong> : réhydratation + <span class=\"kw-ttt\">antibiothérapie</span> le plus souvent.</div>\n      <p>La prise en charge thérapeutique d’une <span class=\"kw-clinique\">diarrhée</span> aiguë associe :</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Réhydratation</td><td>Orale (<span class=\"kw-ttt\">SRO</span>) le plus souvent ; IV si <span class=\"kw-clinique\">déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span>, <span class=\"kw-clinique\">vomissements</span> ou gravité</td></tr>\n          <tr><td>Réduire l’intensité</td><td>Régime sans résidu ; anti-sécrétoire <span class=\"kw-ttt\">racécadotril</span> ; <span class=\"kw-ttt\">diosmectite</span></td></tr>\n          <tr><td>À éviter</td><td><span class=\"kw-ci\">Lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span> si <span class=\"kw-clinique\">diarrhée</span> sanglante, fébrile ou âge &lt;<span class=\"kw-chiffre\"> 30 mois</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td>Non systématique ; selon le <span class=\"kw-def\">terrain</span> et la sévérité</td></tr>\n          <tr><td>Hygiène</td><td>Lavage des mains, désinfection des sanitaires, <span class=\"kw-def\">isolement</span> adapté</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"286-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement de la diarrhée et des colites des antibiotiques","contenu":"<p>Le traitement dépend de la catégorie de <span class=\"kw-clinique\">diarrhée</span> des antibiotiques :</p>\n      <p><strong><span class=\"kw-clinique\">Diarrhée</span> bénigne fonctionnelle</strong> — <span class=\"kw-clinique\">arrêt de l’antibiotique</span> responsable si possible ; elle cède spontanément et rapidement ; pas d’<span class=\"kw-ttt\">antibiothérapie</span>.</p>\n      <p><strong>Colite à <span class=\"kw-etio\">Clostridioides difficile</span></strong> — la prise en charge dépend de la sévérité :</p>\n      <table >\n        <thead><tr><th></th><th>Sans signe de sévérité</th><th>Forme sévère / <span class=\"kw-def\">terrain</span> fragile</th></tr></thead>\n        <tbody>\n          <tr><td>Lieu</td><td>Domicile</td><td><span class=\"kw-alerte\">Hospitalisation</span></td></tr>\n          <tr><td>Mesures générales</td><td>Arrêt de l’ATB responsable ; hydratation orale ; <span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span></td><td>Arrêt de l’ATB ; hydratation IV ; <span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span> ; <span class=\"kw-def\">précautions complémentaires</span> d’hygiène contact</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td><span class=\"kw-ttt\">Vancomycine orale</span> <span class=\"kw-chiffre\">10 jours</span> (1ʳᵉ intention) ; alternatives : <span class=\"kw-ttt\">fidaxomicine</span> ou <span class=\"kw-ttt\">métronidazole</span> 10 j</td><td><span class=\"kw-ttt\">Vancomycine orale</span> + <span class=\"kw-ttt\">métronidazole IV</span> <span class=\"kw-chiffre\">10 jours</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span></td><td>—</td><td><span class=\"kw-alerte\">Colectomie subtotale</span> si colectasie, mégacôlon <span class=\"kw-etio\">toxique</span> ou perforation colique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Récidives</strong> — elles surviennent dans <span class=\"kw-chiffre\">10 à 20 %</span> des cas : <span class=\"kw-ttt\">vancomycine</span> orale ou <span class=\"kw-ttt\">fidaxomicine</span><span class=\"kw-chiffre\"> 10 jours</span>. À la <strong>2ᵉ récidive (3ᵉ épisode)</strong>, la <span class=\"kw-ttt\">transplantation de microbiote fécal</span> est indiquée (&gt;<span class=\"kw-chiffre\"> 85 %</span> de succès).</p>\n      <p>Il n’y a <strong>aucune indication</strong> à un contrôle de <span class=\"kw-bio\">coproculture</span> en fin de traitement. La <span class=\"kw-etio\">Klebsiella oxytoca</span> donne une colite généralement résolutive à l’arrêt de l’ATB (quinolone si elle persiste).</p>\n      <div class=\"callout callout-warn\"><strong>Hygiène — piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">spores de C. difficile résistent aux solutions hydro-alcooliques</span> : se laver les mains au <strong>savon doux</strong> avant l’application de SHA, et désinfecter à l’<strong>eau de Javel</strong> (les détergents classiques sont inefficaces).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 177 — Anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"286-12","rang":"B","rubrique":"Diagnostic positif","titre":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : connaître les principales hypothèses diagnostiques, les examens complémentaires pertinents","contenu":"<p>Chez l’enfant, une <span class=\"kw-clinique\">diarrhée</span> est <span class=\"kw-def\">aiguë</span> si elle évolue depuis <span class=\"kw-chiffre\">&lt; 7 jours</span> (définition pédiatrique distincte de l’adulte). Elle représente <span class=\"kw-chiffre\">7-10 %</span> des hospitalisations, avec environ <span class=\"kw-chiffre\">20 décès/an</span> en France. Deux tableaux à distinguer :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Diarrhée</span> liquidienne</th><th>Diarrhée glairo-sanglante</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Physiopathologie</span></td><td>Malabsorption (<span class=\"kw-def\">osmotique</span>) ; hypersécrétion intestinale d’eau et chlore via <span class=\"kw-def\">entérotoxine</span> (activation de l’adénylcyclase)</td><td>Pénétration et multiplication <span class=\"kw-etio\">bactérienne</span> — destruction des entérocytes ; réaction exsudative <span class=\"kw-etio\">inflammatoire</span> ; atteinte principalement <span class=\"kw-clinique\">colique</span></td></tr>\n          <tr><td>Risque évolutif</td><td><span class=\"kw-alerte\">Déshydratation</span>, <span class=\"kw-etio\">dénutrition</span></td><td><span class=\"kw-alerte\">Dissémination bactériémique systémique</span></td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Vomissements</span> (gastro-entérite) ; <span class=\"kw-clinique\">fébricule</span></td><td><span class=\"kw-clinique\">Syndrome dysentérique</span> — douleurs abdo, syndrome rectal, accès fébriles, signes neuro (<span class=\"kw-etio\">Shigella</span>), selles nombreuses glaireuses sanglantes ± muco-purulentes</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies — <span class=\"kw-clinique\">diarrhée</span> liquidienne</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Virale</span> ++</strong> — <span class=\"kw-etio\">Rotavirus</span> (<strong>1ʳᵉ cause</strong> de <span class=\"kw-clinique\">diarrhée</span> grave avec <span class=\"kw-clinique\">déshydratation</span> avant <span class=\"kw-chiffre\">5 ans</span>) ; <span class=\"kw-etio\">Norovirus</span> (à tout âge) ; <span class=\"kw-etio\">Adénovirus</span>, <span class=\"kw-etio\">entérovirus</span> — contagion via eau, selles, mains souillées</li>\n        <li><strong>Accélération du transit extradigestive</strong> — ORL, urinaires</li>\n        <li><strong><span class=\"kw-etio\">Inflammatoire</span></strong> · <strong>chirurgicale</strong></li>\n        <li><strong>Médicamenteuse</strong> — <span class=\"kw-ttt\">ATB</span> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> +++)</li>\n        <li><strong><span class=\"kw-etio\">Allergique</span></strong> — <span class=\"kw-etio\">APLV</span> ++ (<span class=\"kw-ci\">allergie</span> aux protéines de lait de vache)</li>\n      </ul>\n      <p><strong>Étiologies — <span class=\"kw-clinique\">diarrhée</span> glairo-sanglante</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Bactérienne</span> ++</strong> — parfois <span class=\"kw-etio\">TIAC</span> ; <span class=\"kw-clinique\">voyage récent</span> en zone d’endémie</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Des selles <span class=\"kw-clinique\">glairo-sanglantes</span> n’indiquent pas systématiquement une origine <span class=\"kw-etio\">bactérienne</span> — d’autres mécanismes (<span class=\"kw-etio\">allergique</span>, <span class=\"kw-etio\">inflammatoire</span>) sont possibles.</div>\n      <p><strong>Examens — <span class=\"kw-clinique\">diarrhée</span> liquidienne</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span> — hyperNa, hyperprotidémie, hypoK, acidose, hyperglycémie, IRA fonctionnelle</li>\n        <li><span class=\"kw-bio\">Examen virologique</span> — intérêt épidémiologique</li>\n        <li><span class=\"kw-bio\">Coprocultures</span> — si suspicion <span class=\"kw-etio\">bactérienne</span></li>\n        <li><span class=\"kw-bio\">EPS</span> + <span class=\"kw-bio\">frottis sanguin / goutte épaisse</span> — si retour de voyage</li>\n      </ul>\n      <p><strong>Examens — <span class=\"kw-clinique\">diarrhée</span> glairo-sanglante</strong> :</p>\n      <ul>\n        <li><strong>Bilan <span class=\"kw-etio\">infectieux</span></strong> en cas de signes septiques — <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span> ± <span class=\"kw-bio\">frottis / goutte épaisse</span></li>\n        <li><strong>Indications des <span class=\"kw-bio\">coprocultures</span></strong> — diarrhées glairo-sanglantes invasives ; état septique ; retour de voyage ; contage avec shigellose ; TIAC ; immunodépression</li>\n      </ul>","frequence":1},{"id":"286-13","rang":"A","rubrique":"Identifier une urgence","titre":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","contenu":"<div class=\"callout callout-info\"><strong>Pourquoi le nourrisson ?</strong> Secteur hydrique &gt; adulte, avec un <strong>compartiment extracellulaire prédominant ++</strong>. La <span class=\"kw-clinique\">diarrhée</span> aiguë = <span class=\"kw-alerte\">déshydratation globale</span> (perte d’eau + Na) d’installation rapide.</div>\n      <p><strong>Reconnaître la <span class=\"kw-clinique\">déshydratation</span></strong> — deux compartiments, deux séméiologies :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Déshydratation extracellulaire</span> (DEC)</th><th><span class=\"kw-clinique\">Déshydratation intracellulaire</span> (DIC)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Yeux cernés</span> ; <span class=\"kw-clinique\">pli cutané abdominal</span></td><td><span class=\"kw-clinique\">Muqueuses sèches</span> ; hypotonie des globes oculaires</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dépression de la fontanelle</span> antérieure (<span class=\"kw-chiffre\">&lt; 6 mois</span>)</td><td><span class=\"kw-clinique\">Altération de la conscience</span> ; hypotonie</td></tr>\n          <tr><td><span class=\"kw-alerte\">Tachycardie</span> ; <span class=\"kw-alerte\">hypotension</span> ; <span class=\"kw-alerte\">oligurie</span></td><td><span class=\"kw-clinique\">Fièvre</span> ; <span class=\"kw-clinique\">absence de larmes</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Perte de poids</span></td><td><span class=\"kw-clinique\">Perte de poids</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Calcul de la perte de poids — toujours.</strong> (Poids ancien − Poids récent) / Poids ancien. Chez le <strong>nourrisson</strong> : tenir compte du <strong>gain théorique</strong> entre <span class=\"kw-clinique\">les</span> deux dates (≈ <span class=\"kw-chiffre\">25 g/jour</span>).</div>\n      <p><strong>Corrélation perte de poids ↔ sévérité</strong> :</p>\n      <table >\n        <thead><tr><th>Perte de poids</th><th>Tableau</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 5 %</span></td><td>Pas de <span class=\"kw-clinique\">déshydratation</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">5-10 %</span></td><td>Cernes, sécheresse des muqueuses</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 10 %</span></td><td>Pli cutané persistant — <span class=\"kw-clinique\">déshydratation</span> sévère</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 15 %</span></td><td><span class=\"kw-alerte\">Signes d’hypovolémie</span> — <span class=\"kw-alerte\">état de choc</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes d’<span class=\"kw-alerte\">urgence</span> — <span class=\"kw-clinique\">diarrhée</span> liquidienne</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">À risque</span> de <span class=\"kw-clinique\">déshydratation</span> rapide — nombre quotidien de selles important ; ↗ débit ; <span class=\"kw-clinique\">vomissements</span> répétés ou incoercibles ; impossibilité de réhydratation orale</li>\n        <li><span class=\"kw-clinique\">Déshydratation avérée</span> — cernes, <span class=\"kw-clinique\">fontanelle déprimée</span>, pli cutané, sécheresse muqueuse, absence de larmes, troubles de conscience ou de tonus</li>\n        <li><span class=\"kw-alerte\">Troubles HDM</span> — <span class=\"kw-clinique\">tachycardie</span>, ↗ TRC (<span class=\"kw-chiffre\">&gt; 3 s</span>), extrémités froides, marbrures, ↘ PAS (<strong>tardive chez l’enfant</strong>), pouls mal perçus, apathie/somnolence, hypotonie</li>\n      </ul>\n      <p><strong>Signes d’<span class=\"kw-alerte\">urgence</span> — <span class=\"kw-clinique\">diarrhée</span> glairo-sanglante</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre élevée mal tolérée</span> — enfant <strong>pâle, plaintif, hypotonique, hyporéactif</strong></li>\n        <li><span class=\"kw-alerte\">Sepsis sévère</span> — <span class=\"kw-clinique\">tachycardie</span>, TRC <span class=\"kw-chiffre\">&gt; 3 s</span>, marbrures, extrémités froides, <span class=\"kw-clinique\">frissons</span></li>\n        <li><span class=\"kw-alerte\">Syndrome hémolytique et urémique</span> (<span class=\"kw-etio\">SHU</span>) — plutôt dans <span class=\"kw-clinique\">les</span> suites qu’en phase aiguë</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Critères d’<span class=\"kw-alerte\">hospitalisation</span></strong> :\n        <ul>\n          <li>Âge <span class=\"kw-alerte\">&lt; 3 mois</span></li>\n          <li><span class=\"kw-clinique\">Déshydratation</span> sévère — <span class=\"kw-chiffre\">perte de poids &gt; 10 %</span></li>\n          <li><span class=\"kw-alerte\">Troubles HDM</span> ou neurologiques</li>\n          <li><span class=\"kw-clinique\">Vomissements</span> incoercibles ou bilieux</li>\n          <li>Impossibilité ou échec des <span class=\"kw-ttt\">SRO</span> ; abdomen chirurgical</li>\n          <li><span class=\"kw-clinique\">Diarrhée glairo-sanglante</span> hautement fébrile + trouble HDM</li>\n          <li><span class=\"kw-def\">Terrain</span> — maladie sous-jacente, dénutrition, immunodépression, drépanocytose</li>\n          <li>Mauvaise compliance prévisible (compréhension difficile, milieu social)</li>\n        </ul>\n      </div>","frequence":1},{"id":"286-14","rang":"A","rubrique":"Prise en charge","titre":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","contenu":"<div class=\"callout callout-info\"><strong>Principe.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">SRO</span> sont le <strong>seul traitement indispensable</strong>. Ils n’arrêtent pas la <span class=\"kw-clinique\">diarrhée</span> mais empêchent et corrigent la <span class=\"kw-clinique\">déshydratation</span>. À introduire <strong>précocement</strong>, dès les premiers symptômes.</div>\n      <p><strong>Composition de la SRO (rang C, pour repère)</strong> :</p>\n      <ul>\n        <li>Ratio <span class=\"kw-bio\">glucose/sodium = 1/1</span></li>\n        <li>Électrolytes — <span class=\"kw-bio\">Na 50 mmol/L</span> ; <span class=\"kw-bio\">Cl 80 mmol/L</span> ; <span class=\"kw-bio\">K 20-25 mmol/L</span></li>\n        <li>Sucres — glucose ou dextrine-maltose <span class=\"kw-chiffre\">20-30 g/L</span></li>\n        <li>Osmolarité <span class=\"kw-chiffre\">≈ 250 mOsm/L</span> (respect de l’<span class=\"kw-bio\">osmolarité</span> de la lumière intestinale)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pièges majeurs.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Sodas et jus de fruits = NON ADAPTÉS</span> — trop sucrés, hyperosmolaires (<span class=\"kw-chiffre\">400-550 mOsm/L</span>) et pauvres en électrolytes (Na ≈<span class=\"kw-chiffre\"> 1 mmol/L</span>).</li>\n          <li><span class=\"kw-alerte\">Contre-indication de l’eau pure</span> — risque d’<span class=\"kw-alerte\">hyponatrémie</span>.</li>\n          <li><span class=\"kw-alerte\">SRO « maison »</span> (sel, sucre, eau) — <strong>dangereux</strong> (risque d’aggravation de la <span class=\"kw-clinique\">diarrhée</span> et de troubles hydroélectrolytiques).</li>\n        </ul>\n      </div>\n      <p><strong>Modalités d’administration des SRO</strong> — disponibles en pharmacie sans ordonnance ; 1 sachet à diluer dans <span class=\"kw-chiffre\">200 mL d’eau pure</span>, à proposer froid ; se conservent <span class=\"kw-chiffre\">24 h</span> au réfrigérateur ; administrer <strong>à volonté par petites quantités fractionnées</strong> (≈ toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">15 min</span>) tant que les selles liquides persistent. <strong>Des <span class=\"kw-clinique\">vomissements</span> initiaux ne sont pas une CI</strong>.</p>\n      <p><strong>Plan de prise en charge selon la perte de poids</strong> :</p>\n      <table >\n        <thead><tr><th>Perte de poids</th><th>Examens</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 5 %</span></td><td><strong>Aucun</strong></td><td><strong>Ambulatoire</strong> — RAD avec SRO + consignes de reconsultation</td></tr>\n          <tr><td><span class=\"kw-chiffre\">5-10 %</span></td><td><span class=\"kw-bio\">Iono, urée, créat</span> si échec SRO</td><td><strong>Essai SRO et <span class=\"kw-def\">réévaluation</span></strong> — Succès : RAD + <span class=\"kw-def\">surveillance</span> ambulatoire / Échec : <strong><span class=\"kw-alerte\">hospitalisation</span></strong> + hydratation entérale ou IV</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 10 %</span></td><td><span class=\"kw-bio\">Iono, urée, créat</span></td><td><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> — réhydratation entérale ou IV pendant <span class=\"kw-chiffre\">≥ 6 h</span></td></tr>\n          <tr><td>Trouble HDM</td><td><span class=\"kw-bio\">Iono, urée, créat</span></td><td><span class=\"kw-alerte\">Remplissage vasculaire</span> — <span class=\"kw-ttt\">NaCl 0,9 %</span> <span class=\"kw-chiffre\">10 mL/kg</span> (max <span class=\"kw-chiffre\">500 mL/remplissage</span>), ± à renouveler ; <strong>relais</strong> par perfusion IV plusieurs heures</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Réhydratation entérale continue</strong> — dose de départ <span class=\"kw-chiffre\">200 mL/kg/j</span> de <span class=\"kw-ttt\">SRO</span> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> ne sont pas une <span class=\"kw-ci\">contre-indication</span> ; à privilégier si abord veineux difficile.</p>\n      <p><strong>Réhydratation IV</strong> — <span class=\"kw-ttt\">G5 %</span> + <span class=\"kw-chiffre\">≥ 4 g/L de NaCl</span> ; composition à adapter à l’état clinique et à la <span class=\"kw-bio\">natrémie</span>. Débits :</p>\n      <ul>\n        <li><strong>Nourrisson</strong> — <span class=\"kw-chiffre\">150 mL/kg/j</span></li>\n        <li><strong>Enfant</strong> — <span class=\"kw-chiffre\">100-200 mL/kg/j</span></li>\n      </ul>\n      <p><strong>Renutrition — précoce</strong> :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Allaitement maternel</span></td><td><strong>Pas d’interruption</strong> — à la demande, en alternance avec SRO ; la réhydratation exclusive par SRO ne doit pas excéder <span class=\"kw-chiffre\">4 à 6 h</span></td></tr>\n          <tr><td>Alimentation lactée</td><td>Préparation <strong>standard</strong> — ou <strong>sans lactose</strong> (<span class=\"kw-chiffre\">1 à 2 semaines</span>) si <span class=\"kw-clinique\">diarrhée sévère</span> ou trainante (<span class=\"kw-chiffre\">&gt; 5 jours</span>) ; proposer SRO entre <span class=\"kw-clinique\">les</span> biberons tant que la <span class=\"kw-clinique\">diarrhée</span> persiste</td></tr>\n          <tr><td>Alimentation diversifiée</td><td>Aucun régime particulier</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Antidiarrhéiques</strong> — efficacité modérée, aucun n’est indispensable :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Racécadotril</span>, <span class=\"kw-ttt\">diosmectite</span> — <span class=\"kw-def\">AMM</span> pédiatrique</li>\n        <li><span class=\"kw-ci\">Lopéramide</span> — <span class=\"kw-alerte\">contre-indiqué avant 2 ans</span></li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Antibiothérapie</span></strong> — probabiliste si <span class=\"kw-alerte\">sepsis sévère</span>, retour de voyage, nourrisson &lt;<span class=\"kw-chiffre\"> 3 mois</span>, entourage d’une shigellose, ID/asplénie :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Shigella</span> — <span class=\"kw-ttt\">azithromycine PO 3 j</span> ou <span class=\"kw-ttt\">C3G IV 3 j</span></li>\n        <li><span class=\"kw-etio\">Salmonella</span> — <span class=\"kw-ttt\">C3G IV 3 j</span> (pas d’ATB PO)</li>\n        <li><span class=\"kw-etio\">Yersinia</span> — <span class=\"kw-ttt\">Bactrim PO 5 j</span> ou <span class=\"kw-ttt\">C3G IV 5 j</span></li>\n        <li><span class=\"kw-etio\">Campylobacter</span> — <span class=\"kw-ttt\">azithromycine 3 j</span></li>\n      </ul>","frequence":3},{"id":"286-15","rang":"B","rubrique":"Suivi et/ou Pronostic","titre":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : assurer le suivi","contenu":"<p>Le <span class=\"kw-def\">suivi</span> d’une <span class=\"kw-clinique\">diarrhée</span> aiguë liquidienne du nourrisson repose sur la <strong><span class=\"kw-clinique\">surveillance pondérale quotidienne</span></strong> — la courbe de poids est le critère central d’efficacité de la réhydratation et de la réalimentation.</p>\n      <div class=\"callout callout-warn\"><strong>Consignes de reconsultation</strong> à remettre aux parents pour toute prise en charge ambulatoire :\n        <ul>\n          <li>Réhydratation orale impossible (refus, <span class=\"kw-clinique\">vomissements</span>)</li>\n          <li>Intensification de la <span class=\"kw-clinique\">diarrhée</span></li>\n          <li><span class=\"kw-clinique\">Fièvre</span> persistante mal tolérée</li>\n          <li><span class=\"kw-clinique\">Sang dans les selles</span></li>\n        </ul>\n      </div>\n      <p><strong>Complications à dépister</strong> :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Diarrhée trainante</span> — &gt; <span class=\"kw-chiffre\">5 j</span> après la reprise alimentaire</td><td><strong>Régime sans lactose</strong> pendant <span class=\"kw-chiffre\">1 à 2 semaines</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Neurologique</span></td><td><span class=\"kw-clinique\">Convulsions</span> ; <span class=\"kw-clinique\">hématome sous-dural</span> (HSD) ; <span class=\"kw-alerte\">thromboses veineuses cérébrales</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Rénale</span></td><td><span class=\"kw-alerte\">Nécrose corticale</span> (secondaire au <span class=\"kw-alerte\">choc</span>) ; <span class=\"kw-alerte\">thrombose des veines rénales</span> (exceptionnelle, &gt; <span class=\"kw-chiffre\">6 mois</span>)</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Sepsis</span> <span class=\"q\">— <span class=\"kw-clinique\">diarrhée</span> fébrile à risque</span></strong></p><p><span class=\"kw-bio\">hémocultures</span> ; une <span class=\"kw-clinique\">diarrhée fébrile</span> peut révéler tout <span class=\"kw-def\">sepsis</span> — éliminer un <span class=\"kw-etio\">paludisme</span> au retour de zone d'endémie</p><ul><li><span class=\"kw-def\">Score</span> <span class=\"kw-def\">qSOFA ≥ 2</span> : <span class=\"kw-clinique\">FR</span> <span class=\"kw-chiffre\">≥ 22/min</span> · <span class=\"kw-clinique\">PAS</span> <span class=\"kw-chiffre\">≤ 100 mmHg</span> · <span class=\"kw-clinique\">trouble de conscience</span> (<span class=\"kw-clinique\">Glasgow &lt; 15</span>)</li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">valvulopathie</span> (EI), sujet âgé, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">immunodépression</span> (<span class=\"kw-etio\">VIH CD4 &lt; 200</span>, <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul><p><strong><span class=\"kw-clinique\">Déshydratation</span> aiguë <span class=\"q\">— complication majeure</span></strong></p><p><span class=\"kw-ttt\">réhydratation</span> sans délai — <span class=\"kw-ttt\">SRO</span> ou <span class=\"kw-ttt\">IV</span> selon la gravité</p><ul><li>Sujets à risque : <span class=\"kw-alerte\">nourrisson</span>, personne âgée dépendante, patient polymédiqué (<span class=\"kw-ttt\">diurétiques</span>)</li><li>D'autant plus rapide si <span class=\"kw-clinique\">diarrhée liquide intense</span> + <span class=\"kw-clinique\">vomissements</span> empêchant la réhydratation orale</li><li>Pertes en <span class=\"kw-bio\">eau</span>, <span class=\"kw-bio\">sodium</span>, <span class=\"kw-bio\">potassium</span>, <span class=\"kw-bio\">bicarbonates</span></li></ul><p><strong>Syndrome occlusif <span class=\"q\">— occlusion fonctionnelle</span></strong></p><p><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> pour éliminer une <span class=\"kw-alerte\">urgence</span> chirurgicale (<span class=\"kw-alerte\">perforation</span>, occlusion)</p><ul><li><span class=\"kw-clinique\">Iléus</span> fonctionnel (sans obstacle) : <span class=\"kw-etio\">colite grave</span> (<span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">C. difficile</span>), <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-ci\">lopéramide</span></li></ul><p><strong>Retour de zone d'endémie palustre</strong></p><ul><li>Éliminer un <span class=\"kw-etio\">accès palustre</span> en systématique : <span class=\"kw-bio\">frottis sanguin</span> + <span class=\"kw-bio\">goutte épaisse</span></li><li>La <span class=\"kw-etio\">fièvre typhoïde</span> ne donne une <span class=\"kw-clinique\">diarrhée</span> qu'en phase d'état, pas en phase d'invasion</li></ul>","hospit":"<p><strong>Adulte <span class=\"q\">— critères d'<span class=\"kw-alerte\">hospitalisation</span></span></strong></p><ul><li>Âge <span class=\"kw-chiffre\">&lt; 3 mois</span></li><li><span class=\"kw-alerte\">Déshydratation &gt; 8 % du poids</span>, <span class=\"kw-alerte\">collapsus</span>, signes de <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">syndrome occlusif</span></li><li><span class=\"kw-clinique\">Diarrhée fébrile</span> au retour d'un pays d'endémie palustre</li><li><span class=\"kw-clinique\">Vomissements</span> rendant la réhydratation orale impossible</li><li><span class=\"kw-alerte\">Décompensation</span> d'une <span class=\"kw-def\">comorbidité</span> ; <span class=\"kw-def\">isolement</span> ou milieu social défavorisé</li></ul><p><strong>Nourrisson &amp; enfant <span class=\"q\">— critères d'<span class=\"kw-alerte\">hospitalisation</span></span></strong></p><ul><li>Âge <span class=\"kw-alerte\">&lt; 3 mois</span></li><li><span class=\"kw-alerte\">Déshydratation sévère</span> — <span class=\"kw-chiffre\">perte de poids &gt; 10 %</span></li><li><span class=\"kw-alerte\">Troubles hémodynamiques</span> ou neurologiques</li><li><span class=\"kw-clinique\">Vomissements</span> incoercibles ou bilieux</li><li>Échec ou impossibilité des <span class=\"kw-ttt\">SRO</span> ; <span class=\"kw-alerte\">abdomen chirurgical</span></li><li><span class=\"kw-clinique\">Diarrhée glairo-sanglante</span> hautement fébrile + trouble hémodynamique</li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">dénutrition</span>, <span class=\"kw-etio\">immunodépression</span>, <span class=\"kw-etio\">drépanocytose</span> ; mauvaise compliance prévisible</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Sepsis</span> : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">altération de la conscience</span>, <span class=\"kw-clinique\">tachypnée</span> (<span class=\"kw-def\">qSOFA ≥ 2</span>)</li><li><span class=\"kw-alerte\">Déshydratation sévère</span> : <span class=\"kw-clinique\">pouls rapide</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pli cutané persistant</span>, <span class=\"kw-clinique\">sécheresse des muqueuses</span></li><li><span class=\"kw-alerte\">Défense abdominale</span> → complication (<span class=\"kw-alerte\">perforation</span>)</li><li><span class=\"kw-alerte\">Arrêt des matières et des gaz</span> → occlusion</li><li>Nourrisson : <span class=\"kw-alerte\">troubles hémodynamiques</span> — <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">TRC</span> <span class=\"kw-chiffre\">&gt; 3 s</span>, marbrures, extrémités froides, <span class=\"kw-clinique\">↘ PAS tardive</span>, apathie/somnolence</li><li>Nourrisson : <span class=\"kw-alerte\">déshydratation &gt; 15 %</span> → signes d'hypovolémie, <span class=\"kw-alerte\">état de choc</span></li><li><span class=\"kw-alerte\">Syndrome hémolytique et urémique</span> (<span class=\"kw-def\">SHU</span>) — plutôt dans <span class=\"kw-clinique\">les</span> suites</li></ul>","principes":"<p><span class=\"kw-clinique\">Diarrhée</span> <strong>sécrétoire</strong> : traitement dominé par la <span class=\"kw-ttt\">réhydratation hydroélectrolytique</span>. <span class=\"kw-clinique\">Diarrhée</span> <strong>invasive</strong> : réhydratation + <span class=\"kw-ttt\">antibiothérapie</span> le plus souvent. La majorité des diarrhées infectieuses guérissent spontanément en <span class=\"kw-chiffre\">&lt; 5 jours</span> sans exploration.</p><p><strong>Réhydratation <span class=\"q\">— pierre angulaire</span></strong></p><p><span class=\"kw-clinique\">surveillance pondérale quotidienne</span></p><ul><li>Voie orale le plus souvent : <span class=\"kw-ttt\">SRO</span> (sodium, glucose, potassium, agent alcalinisant)</li><li>Voie <span class=\"kw-ttt\">IV</span> si <span class=\"kw-alerte\">déshydratation ≥ 8 %</span>, <span class=\"kw-clinique\">vomissements</span> importants, <span class=\"kw-alerte\">signes de gravité</span> ou troubles ioniques</li><li>Schéma IV : <span class=\"kw-chiffre\">50 % des pertes en 6 h</span>, puis le reste sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">18 h</span> restantes</li></ul><p><strong>Traitements symptomatiques</strong></p><p><span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span> si <span class=\"kw-alerte\">diarrhée sanglante</span>, <span class=\"kw-alerte\">fébrile</span> ou <span class=\"kw-chiffre\">âge &lt; 30 mois</span></p><ul><li>Maintien de l'alimentation : <span class=\"kw-clinique\">régime sans résidu</span> (riz, pâtes, biscuits salés) ; éviter lait, crudités, fibres</li><li>Anti-sécrétoire <span class=\"kw-ttt\">racécadotril</span> ; <span class=\"kw-ttt\">diosmectite</span> (efficacité modérée, non indispensables)</li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> <span class=\"q\">— non systématique</span></strong></p><p>d'autant plus efficace si débutée <span class=\"kw-chiffre\">&lt; 48 h</span> ; <span class=\"kw-bio\">coproculture avant antibiothérapie</span></p><ul><li>Inutile si contexte <span class=\"kw-etio\">viral</span>, tableau cholériforme/gastro-entéritique non sévère sans <span class=\"kw-def\">terrain</span> à risque</li><li>Indiquée si <span class=\"kw-def\">terrain</span> à risque (âges extrêmes, <span class=\"kw-etio\">immunodépression</span>, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">valvulopathie</span>), <span class=\"kw-clinique\">diarrhée dysentérique fébrile</span>, ou forme sévère (<span class=\"kw-chiffre\">T° &gt; 38,5 °C</span> ou <span class=\"kw-chiffre\">&gt; 6 selles/j</span>)</li><li>Probabiliste : <span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">ciprofloxacine</span> PO <span class=\"kw-chiffre\">1-3 j</span> ; si voie orale impossible <span class=\"kw-ttt\">ceftriaxone</span> ± <span class=\"kw-ttt\">métronidazole IV</span></li></ul><p><strong>Colite à <span class=\"kw-etio\">C. difficile</span> <span class=\"q\">— <span class=\"kw-clinique\">diarrhée</span> des antibiotiques</span></strong></p><p><span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span> ; <span class=\"kw-alerte\">spores résistantes aux SHA</span> → savon doux puis <span class=\"kw-ttt\">eau de Javel</span></p><ul><li><span class=\"kw-clinique\">Diarrhée bénigne fonctionnelle</span> : arrêt de l'<span class=\"kw-ttt\">antibiotique</span> responsable, cède spontanément — pas d'<span class=\"kw-ttt\">antibiothérapie</span></li><li>Forme non sévère : <span class=\"kw-ttt\">vancomycine orale</span> <span class=\"kw-chiffre\">10 j</span> (alternatives <span class=\"kw-ttt\">fidaxomicine</span> ou <span class=\"kw-ttt\">métronidazole</span>)</li><li>Forme sévère / <span class=\"kw-def\">terrain</span> fragile : <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-ttt\">vancomycine orale + métronidazole IV</span> <span class=\"kw-chiffre\">10 j</span> ; <span class=\"kw-alerte\">colectomie subtotale</span> si <span class=\"kw-alerte\">mégacôlon toxique</span> ou <span class=\"kw-alerte\">perforation</span></li></ul><p><strong>Nourrisson &amp; enfant <span class=\"q\">— SRO + renutrition précoce</span></strong></p><p><span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span> <span class=\"kw-chiffre\">avant 2 ans</span> ; <span class=\"kw-ttt\">racécadotril</span> / <span class=\"kw-ttt\">diosmectite</span> ont l'AMM pédiatrique</p><ul><li><span class=\"kw-ttt\">SRO</span> = <strong>seul traitement indispensable</strong> ; à volonté, par petites quantités fractionnées (<span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> ne sont pas une CI)</li><li><span class=\"kw-alerte\">Sodas, jus de fruits, eau pure et SRO « maison » dangereux</span> (hyperosmolaires / risque d'<span class=\"kw-alerte\">hyponatrémie</span>)</li><li>Renutrition <strong>précoce</strong> : <span class=\"kw-clinique\">allaitement maternel</span> non interrompu ; réhydratation exclusive par SRO ≤ <span class=\"kw-chiffre\">4-6 h</span></li><li>Trouble hémodynamique : <span class=\"kw-alerte\">remplissage</span> <span class=\"kw-ttt\">NaCl 0,9 %</span> <span class=\"kw-chiffre\">10 mL/kg</span></li></ul>","suivi":"<p>Chez le sujet <span class=\"kw-chiffre\">&gt; 75 ans</span>, la <span class=\"kw-def\">mortalité</span> tient aux accidents de <span class=\"kw-clinique\">déshydratation</span> et à l'<span class=\"kw-alerte\">hypoperfusion des organes vitaux</span>, avec un pic de mortalité <span class=\"kw-chiffre\">8 à 10 jours</span> après le début de la <span class=\"kw-clinique\">diarrhée</span> (souvent déjà résolue).</p><p><strong><span class=\"kw-def\">Surveillance</span> &amp; reconsultation</strong></p><ul><li><span class=\"kw-clinique\">Surveillance pondérale quotidienne</span> — critère central d'efficacité de la réhydratation</li><li>Consignes de reconsultation (ambulatoire) : réhydratation orale impossible, <span class=\"kw-clinique\">intensification de la diarrhée</span>, <span class=\"kw-clinique\">fièvre persistante</span> mal tolérée, <span class=\"kw-clinique\">sang dans les selles</span></li></ul><p><strong>Complications à dépister <span class=\"q\">— nourrisson &amp; enfant</span></strong></p><ul><li><span class=\"kw-clinique\">Diarrhée trainante</span> (<span class=\"kw-chiffre\">&gt; 5 j</span>) → <span class=\"kw-ttt\">régime sans lactose</span> <span class=\"kw-chiffre\">1-2 semaines</span></li><li>Neurologiques : <span class=\"kw-clinique\">convulsions</span>, <span class=\"kw-alerte\">hématome sous-dural</span>, <span class=\"kw-alerte\">thromboses veineuses cérébrales</span></li><li>Rénales : <span class=\"kw-alerte\">nécrose corticale</span> (post-<span class=\"kw-alerte\">choc</span>), <span class=\"kw-alerte\">thrombose des veines rénales</span></li></ul><p><strong>Colite à <span class=\"kw-etio\">C. difficile</span> <span class=\"q\">— <span class=\"kw-def\">suivi</span></span></strong></p><ul><li><span class=\"kw-bio\">Aucun contrôle de coproculture</span> en fin de traitement</li><li>Récidives dans <span class=\"kw-chiffre\">10-20 %</span> des cas : <span class=\"kw-ttt\">vancomycine</span> ou <span class=\"kw-ttt\">fidaxomicine</span> <span class=\"kw-chiffre\">10 j</span></li><li>2ᵉ récidive (3ᵉ épisode) → <span class=\"kw-ttt\">transplantation de microbiote fécal</span> (&gt; <span class=\"kw-chiffre\">85 %</span> de succès)</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/clostridioides-difficile-colitis","label":"radiopaedia.org"}],"cards":[{"i":"00a10915393f","n":286,"o":"286-1","u":"Définition","t":"Connaître la définition d’une diarrhée aiguë","q":"Comment distingue-t-on une diarrhée aiguë d'une diarrhée prolongée et d'une diarrhée chronique ?","a":"<ul><li>Une diarrhée <strong>aiguë</strong> évolue depuis <strong>moins de 2 semaines</strong>.</li><li>Une diarrhée <strong>prolongée</strong> dure <strong>de 2 à 4 semaines</strong>.</li><li>Une diarrhée <strong>chronique</strong> évolue depuis <strong>plus de 1 mois</strong> (> 4 semaines).</li></ul>"},{"i":"30ec24df2e02","n":286,"o":"286-1","u":"Définition","t":"Connaître la définition d’une diarrhée aiguë","q":"Qu'est-ce qui caractérise une diarrhée pour la qualifier d'« aiguë » ?","a":"<p>Une diarrhée est qualifiée d'« aiguë » lorsqu'elle évolue depuis <strong>moins de 2 semaines</strong>.</p>"},{"i":"13ab1d2e4136","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Quel est le principe majeur de la prise en charge thérapeutique d'une diarrhée aiguë, qu'elle soit sécrétoire ou invasive ?","a":"<p>Le principe majeur est la <strong>réhydratation hydroélectrolytique</strong>, qui est fondamentale pour compenser les pertes liquidiennes et électrolytiques.</p>"},{"i":"46d2a4372808","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Dans quels cas le lopéramide est-il contre-indiqué dans la prise en charge d'une diarrhée aiguë ?","a":"<p>Le lopéramide est contre-indiqué si la diarrhée est <strong>sanglante</strong>, <strong>fébrile</strong> ou chez les enfants de moins de <strong>30 mois</strong>.</p>"},{"i":"56c37f591a20","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Comment peut-on réduire l'intensité des symptômes dans la prise en charge d'une diarrhée aiguë ?","a":"<ul><li>Par un <strong>régime sans résidu</strong>.</li><li>L'utilisation d'un <strong>anti-sécrétoire</strong> comme le <strong>racécadotril</strong>.</li><li>L'utilisation d'un <strong>adsorbant intestinal</strong> tel que la <strong>diosmectite</strong>.</li></ul>"},{"i":"79ddab6de497","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Quelles sont les modalités de réhydratation dans la prise en charge d'une diarrhée aiguë ?","a":"<ul><li>Le plus souvent, la réhydratation est <strong>orale</strong> à l'aide de <strong>Sels de Réhydratation Orale (SRO)</strong>.</li><li>Une réhydratation <strong>intraveineuse (IV)</strong> est indiquée en cas de déshydratation <strong>≥ 8 %</strong>, de vomissements importants ou de signes de gravité.</li></ul>"},{"i":"cdbbbd8566ca","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Quelles sont les mesures d'hygiène préconisées dans la prise en charge et la prévention de la transmission d'une diarrhée aiguë ?","a":"<ul><li>Le <strong>lavage des mains</strong> rigoureux.</li><li>La <strong>désinfection des sanitaires</strong>.</li><li>Un <strong>isolement adapté</strong> du patient si nécessaire.</li></ul>"},{"i":"d2c178831712","n":286,"o":"286-10","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’une diarrhée aiguë","q":"Quelle est la place de l'antibiothérapie dans la prise en charge d'une diarrhée aiguë ?","a":"<p>L'antibiothérapie n'est <strong>pas systématique</strong>. Elle est décidée en fonction du <strong>terrain</strong> du patient et de la <strong>sévérité</strong> de la diarrhée.</p>"},{"i":"0449118213cb","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Quelles sont les mesures générales en cas de colite à <em>Clostridioides difficile</em> ?","a":"<p>Les mesures générales comprennent :</p><ul><li>L'<strong>arrêt de l'antibiotique responsable</strong>.</li><li>Une <strong>hydratation orale</strong> pour les formes sans signe de sévérité ou par <strong>voie intraveineuse</strong> pour les formes sévères/terrains fragiles.</li><li>Le <strong>lopéramide est contre-indiqué</strong>.</li><li>Des <strong>précautions complémentaires d'hygiène par contact</strong> en cas d'hospitalisation.</li></ul>"},{"i":"292f7aa97cf3","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Quelles sont les recommandations d'hygiène spécifiques en cas de colite à <em>Clostridioides difficile</em> ?","a":"<p>Il est important de savoir que les <strong>spores de <em>Clostridioides difficile</em> résistent aux solutions hydro-alcooliques</strong>. Il faut donc se <strong>laver les mains au savon doux</strong> avant l'application de solution hydro-alcoolique et désinfecter les surfaces avec de l'<strong>eau de Javel</strong>, les détergents classiques étant inefficaces.</p>"},{"i":"51ea9b2f272a","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Comment prendre en charge une colite due à <em>Klebsiella oxytoca</em> ?","a":"<p>La colite due à <em>Klebsiella oxytoca</em> est généralement <strong>résolutive à l'arrêt de l'antibiotique responsable</strong>. Si elle persiste, une <strong>quinolone</strong> peut être administrée.</p>"},{"i":"822b45ebcc00","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Quelle est la prise en charge des récidives de colite à <em>Clostridioides difficile</em> ?","a":"<p>Après une première récidive, le traitement repose sur la <strong>vancomycine orale</strong> ou la <strong>fidaxomicine pendant 10 jours</strong>. À la deuxième récidive (troisième épisode), la <strong>transplantation de microbiote fécal</strong> est indiquée et présente un succès supérieur à 85%.</p>"},{"i":"a9edae17bff2","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Quel est le traitement recommandé pour une colite à <em>Clostridioides difficile</em> grave ou sur terrain fragile ?","a":"<p>Le traitement recommandé pour une colite à <em>Clostridioides difficile</em> grave ou sur terrain fragile est l'association <strong>vancomycine orale et métronidazole IV pendant 10 jours</strong>. Une <strong>colectomie subtotale</strong> est indiquée en cas de colectasie, de mégacôlon toxique ou de perforation colique.</p>"},{"i":"d6c9010179f2","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Quelle est l'antibiothérapie de première intention pour une colite à <em>Clostridioides difficile</em> sans signe de sévérité ?","a":"<p>L'antibiothérapie de première intention pour une colite à <em>Clostridioides difficile</em> sans signe de sévérité est la <strong>vancomycine orale pendant 10 jours</strong>. Les alternatives sont la <strong>fidaxomicine</strong> ou le <strong>métronidazole</strong>, également pendant 10 jours.</p>"},{"i":"fcebc3c53e07","n":286,"o":"286-11","u":"Prise en charge","t":"Connaître le traitement de la diarrhée et des colites des antibiotiques","q":"Comment prend-on en charge une diarrhée des antibiotiques bénigne fonctionnelle ?","a":"<p>La prise en charge d'une diarrhée des antibiotiques bénigne fonctionnelle repose sur l'<strong>arrêt de l'antibiotique responsable</strong> si possible. Elle cède alors spontanément et rapidement, et ne nécessite <strong>pas d'antibiothérapie spécifique</strong>.</p>"},{"i":"116d34ea429e","n":286,"o":"286-13","u":"Identifier une urgence","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","q":"Comment évalue-t-on le degré de déshydratation chez le nourrisson à partir de la perte de poids et ses implications en termes de sévérité ?","a":"<p>Le degré de déshydratation est évalué par le calcul de la <strong>perte de poids</strong> : (Poids ancien - Poids récent) / Poids ancien. Chez le nourrisson, il faut tenir compte d'un gain théorique de <strong>25 g/jour</strong>.</p><ul><li>Perte de poids <strong>&lt; 5 %</strong> : pas de déshydratation significative.</li><li>Perte de poids entre <strong>5-10 %</strong> : cernes, sécheresse des muqueuses.</li><li>Perte de poids <strong>&gt; 10 %</strong> : pli cutané persistant, déshydratation sévère.</li><li>Perte de poids <strong>&gt; 15 %</strong> : signes d'hypovolémie, état de choc.</li></ul>"},{"i":"4d3e799b23f6","n":286,"o":"286-13","u":"Identifier une urgence","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","q":"Quels sont les signes d'urgence d'une diarrhée aiguë liquide chez l'enfant et le nourrisson ?","a":"<ul><li><strong>À risque de déshydratation rapide</strong> : nombre quotidien de selles important, augmentation du débit, vomissements répétés ou incoercibles, impossibilité de réhydratation orale (SRO).</li><li><strong>Déshydratation avérée</strong> : cernes, fontanelle déprimée, pli cutané, sécheresse muqueuse, absence de larmes, troubles de conscience ou de tonus.</li><li><strong>Troubles hémodynamiques (HDM)</strong> : <strong>tachycardie</strong>, TRC (temps de recoloration capillaire) <strong>&gt; 3 secondes</strong>, extrémités froides, marbrures, diminution de la pression artérielle systolique (tardive chez l'enfant), pouls mal perçus, apathie/somnolence, hypotonie.</li></ul>"},{"i":"b31f00217a90","n":286,"o":"286-13","u":"Identifier une urgence","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","q":"Pourquoi la déshydratation est-elle plus rapide et sévère chez le nourrisson en cas de diarrhée aiguë ?","a":"<p>Chez le nourrisson, le <strong>secteur hydrique</strong> représente une proportion plus importante du poids corporel que chez l'adulte, avec une prédominance du <strong>compartiment extracellulaire</strong>. La diarrhée aiguë entraîne une perte rapide d'eau et de sodium, impactant directement ce compartiment volumineux et prédisposant à une déshydratation sévère.</p>"},{"i":"eb9a9a4d7a9d","n":286,"o":"286-13","u":"Identifier une urgence","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","q":"Quels sont les signes cliniques permettant de différencier une déshydratation extracellulaire (DEC) d'une déshydratation intracellulaire (DIC) chez le nourrisson ?","a":"<ul><li>Les signes de <strong>déshydratation extracellulaire (DEC)</strong> incluent : les <strong>yeux cernés</strong>, le <strong>pli cutané abdominal</strong> persistant, la <strong>dépression de la fontanelle antérieure</strong> (avant 6 mois), la tachycardie, l'hypotension et l'oligurie.</li><li>Les signes de <strong>déshydratation intracellulaire (DIC)</strong> incluent : des <strong>muqueuses sèches</strong>, une <strong>hypotonie des globes oculaires</strong>, une altération de la conscience, une hypotonie, de la fièvre, une absence de larmes et une perte de poids.</li></ul>"},{"i":"fc3114b3fb30","n":286,"o":"286-13","u":"Identifier une urgence","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : identifier des situations d’urgence","q":"Quels sont les critères d'hospitalisation devant une diarrhée aiguë chez le nourrisson et l'enfant ?","a":"<ul><li>Âge <strong>&lt; 3 mois</strong>.</li><li><strong>Déshydratation sévère</strong> (perte de poids <strong>> 10 %</strong>).</li><li><strong>Troubles hémodynamiques</strong> ou neurologiques.</li><li><strong>Vomissements incoercibles</strong> ou bilieux.</li><li>Impossibilité ou <strong>échec des SRO</strong> (solutions de réhydratation orale) ; abdomen chirurgical.</li><li>Diarrhée <strong>glairo-sanglante</strong> hautement fébrile associée à des signes de troubles hémodynamiques.</li><li>Terrain particulier : maladie sous-jacente, <strong>dénutrition</strong>, immunodépression, drépanocytose.</li><li>Mauvaise compliance prévisible des parents (compréhension difficile, milieu social).</li></ul>"},{"i":"08175e0d50fe","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Quels sont les pièges à éviter concernant l'administration de liquides et l'utilisation de SRO lors de la réhydratation d'un nourrisson ou d'un enfant déshydraté ?","a":"<ul><li>Les <strong>sodas et jus de fruits sont non adaptés</strong> car trop sucrés, hyperosmolaires (400-550 mOsm/L) et pauvres en électrolytes.</li><li>L'<strong>eau pure est contre-indiquée</strong>, risquant une hyponatrémie.</li><li>Les <strong>SRO « maison » sont dangereux</strong> (risque d'aggravation de la diarrhée et de troubles hydroélectrolytiques).</li></ul>"},{"i":"3b352e7e4907","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Dans quels cas une antibiothérapie probabiliste est-elle indiquée en cas de diarrhée aiguë chez l'enfant ou le nourrisson ?","a":"<p>Une antibiothérapie probabiliste est indiquée en cas de <strong>sepsis sévère</strong>, de <strong>retour de voyage</strong>, chez le <strong>nourrisson de moins de 3 mois</strong>, en cas d'entourage d'une <strong>shigellose</strong>, ou chez un patient <strong>immunodéprimé/asplénique</strong>.</p>"},{"i":"47c84ed3ba76","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Quelles sont les caractéristiques de la composition des SRO recommandées (valeurs de référence) ?","a":"<ul><li>Ratio glucose/sodium = <strong>1/1</strong></li><li>Électrolytes : <strong>Na 50 mmol/L</strong> ; <strong>Cl 80 mmol/L</strong> ; <strong>K 20-25 mmol/L</strong></li><li>Sucres : glucose ou dextrine-maltose <strong>20-30 g/L</strong></li><li>Osmolarité : environ <strong>250 mOsm/L</strong> (respecte l'osmolarité de la lumière intestinale)</li></ul>"},{"i":"6a336c83a9b8","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Comment les SRO doivent-elles être administrées à un nourrisson ou un enfant déshydraté ?","a":"<p>Les SRO doivent être administrées <strong>à volonté</strong>, par <strong>petites quantités fractionnées</strong> (environ toutes les <strong>15 minutes</strong>), tant que les selles liquides persistent. Un sachet doit être dilué dans <strong>200 mL d'eau pure</strong> et proposé froid. Les vomissements initiaux ne sont pas une contre-indication.</p>"},{"i":"6c080f8300be","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Comment adapter la renutrition chez le nourrisson et l'enfant atteint de diarrhée aiguë et déshydraté, en fonction du type d'alimentation habituelle ?","a":"<ul><li><strong>Allaitement maternel :</strong> Ne pas interrompre, à la demande, en alternance avec SRO. La réhydratation exclusive par SRO ne doit pas excéder <strong>4 à 6 heures</strong>.</li><li><strong>Alimentation lactée :</strong> Reprendre une préparation standard. Une préparation <strong>sans lactose</strong> peut être envisagée pendant <strong>1 à 2 semaines</strong> en cas de diarrhée sévère ou traînante (> 5 jours). Proposer SRO entre les biberons.</li><li><strong>Alimentation diversifiée :</strong> Aucun régime particulier.</li></ul>"},{"i":"8234c170f50c","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Quelle est la conduite à tenir face à une diarrhée aiguë liquidienne et une déshydratation chez le nourrisson et l'enfant selon la perte de poids ?","a":"<ul><li><strong>Perte de poids &lt; 5 % :</strong> Prise en charge <strong>ambulatoire</strong> avec SRO et consignes de reconsultation. Pas d'examens complémentaires.</li><li><strong>Perte de poids 5-10 % :</strong> Essai de SRO et réévaluation. Si succès, retour à domicile avec surveillance; si échec, <strong>hospitalisation</strong> avec hydratation entérale ou IV. Bilan iono, urée, créatinine si échec des SRO.</li><li><strong>Perte de poids &gt; 10 % ou trouble hémodynamique :</strong> <strong>Hospitalisation</strong> systématique avec réhydratation entérale ou IV pendant au moins 6 heures, voire remplissage vasculaire (<strong>NaCl 0,9 % 10 mL/kg</strong>) si troubles hémodynamiques. Bilan iono, urée, créatinine.</li></ul>"},{"i":"a4e848971e5c","n":286,"o":"286-14","u":"Prise en charge","t":"Diarrhée aiguë liquidienne et déshydratation chez le nourrisson et l’enfant : planifier la prise en charge","q":"Quel est le traitement de première intention et indispensable pour la diarrhée aiguë chez le nourrisson et l'enfant, et quel est son mécanisme d'action principal ?","a":"<p>Le traitement indispensable est l'administration de <strong>Solutions de Réhydratation Orale (SRO)</strong>. Elles n'arrêtent pas la diarrhée mais visent à <strong>prévenir et corriger la déshydratation</strong>.</p>"},{"i":"98bb6f9d2f32","n":286,"o":"286-2","u":"Définition","t":"Connaître la définition du syndrome dysentérique","q":"Quel mécanisme physiopathologique le syndrome dysentérique évoque-t-il ?","a":"<p>Le syndrome dysentérique témoigne d'un mécanisme <strong>entéro-invasif</strong> avec atteinte de la muqueuse <strong>colique ou iléo-colique</strong>.</p>"},{"i":"9b57396fade8","n":286,"o":"286-2","u":"Définition","t":"Connaître la définition du syndrome dysentérique","q":"En quoi consiste le syndrome rectal, composante du syndrome dysentérique ?","a":"<p>Le syndrome rectal est caractérisé par :<ul><li>Les <strong>épreintes</strong> : douleurs coliques/pelviennes avec spasme rectal, soulagées par l'émission de selles.</li><li>Le <strong>ténesme</strong> : tension douloureuse de la région anale, persistant après l'exonération.</li><li>Les <strong>faux besoins</strong> : fausse envie impérieuse d'aller à la selle.</li></ul>L'émission de selles glairo-sanglantes suggère une atteinte colique distale (rectite), le sang n'ayant pas eu le temps d'être digéré.</p>"},{"i":"f25f64404ac3","n":286,"o":"286-2","u":"Définition","t":"Connaître la définition du syndrome dysentérique","q":"Quelle est la définition du syndrome dysentérique en clinique ?","a":"<p>Le syndrome dysentérique est caractérisé par l'association de <ul><li>selles <strong>afécales</strong>, <strong>glaireuses et sanglantes</strong> (parfois <strong>mucopurulentes</strong>)</li><li>des <strong>douleurs abdominales</strong></li><li>un <strong>syndrome rectal</strong>.</li></ul></p>"},{"i":"521357d9d6ad","n":286,"o":"286-3","u":"Épidémiologie","t":"Connaître l’incidence et la prévalence des diarrhées aiguës","q":"Quelle est la proportion de la population française qui consulte chaque année un médecin pour une diarrhée aiguë ?","a":"<p>Chaque année en France, <strong>5 % des habitants</strong> consultent pour une diarrhée évoluant <strong>plus de 24 heures</strong>.</p>"},{"i":"595fe2ef1409","n":286,"o":"286-3","u":"Épidémiologie","t":"Connaître l’incidence et la prévalence des diarrhées aiguës","q":"Quelle est l'incidence annuelle des épisodes digestifs aigus (diarrhée ou vomissements) dans la population générale ?","a":"<p>L'incidence annuelle est d'environ <strong>un épisode digestif aigu par an et par habitant</strong>.</p>"},{"i":"5ee2e4bfd5e2","n":286,"o":"286-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","q":"Quels sont les contextes anamnestiques spécifiques à rechercher lors de l'interrogatoire d'une diarrhée aiguë ?","a":"<p>Les contextes anamnestiques spécifiques à rechercher sont :</p><ul><li>Un <strong>voyage récent</strong> (infection tropicale, parasitose).</li><li>Une <strong>antibiothérapie de moins de 3 mois</strong> (suspicion de <em>Clostridioides difficile</em>).</li><li>Des <strong>cas groupés</strong> (familial, restauration collective) orientant vers une TIAC.</li><li>Un <strong>contage</strong> ou un <strong>contexte épidémique</strong>.</li></ul>"},{"i":"c6e459878127","n":286,"o":"286-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","q":"Quels éléments de l'interrogatoire et de l'examen clinique orientent vers une diarrhée de mécanisme <strong>sécrétoire</strong> ?","a":"<p>Une diarrhée de mécanisme sécrétoire est suspectée devant :</p><ul><li>Des selles <strong>hydriques</strong>, aqueuses (« eau de riz »).</li><li>Une fièvre <strong>habituellement absente</strong>.</li><li>Un <strong>syndrome rectal absent</strong>.</li><li>Un siège au niveau de l'intestin grêle.</li></ul>"},{"i":"e521e5a6aceb","n":286,"o":"286-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","q":"Quels sont les signes cliniques de gravité à rechercher impérativement lors de l'examen clinique d'une diarrhée aiguë ?","a":"<p>Lors de l'examen clinique d'une diarrhée aiguë, il faut impérativement apprécier :</p><ul><li>Les <strong>signes de gravité</strong> (notamment les signes de <strong>sepsis</strong>).</li><li>Les signes de <strong>déshydratation</strong>.</li><li>La présence d'une <strong>défense abdominale</strong> (rechercher une complication comme une <strong>perforation</strong>).</li><li>Un <strong>arrêt des matières et des gaz</strong> (rechercher une <strong>occlusion</strong>).</li></ul>"},{"i":"ece50a94c846","n":286,"o":"286-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","q":"Quels éléments de l'interrogatoire et de l'examen clinique orientent vers une diarrhée de mécanisme <strong>invasif</strong> ?","a":"<p>Une diarrhée de mécanisme invasif est suspectée devant :</p><ul><li>Des selles <strong>glairo-sanglantes</strong> et afécales.</li><li>Une <strong>fièvre présente</strong>.</li><li>Un <strong>syndrome rectal</strong> (épreintes, ténesme, faux besoins).</li><li>Un siège colique.</li></ul>"},{"i":"5b5fc6b87ce9","n":286,"o":"286-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","q":"Quelles sont les caractéristiques principales de la diarrhée bénigne fonctionnelle liée aux antibiotiques ?","a":"<p>Elle est <strong>fréquente</strong>, résulte d'une <strong>dysbiose</strong> avec baisse de la fermentation des sucres. Elle apparaît <strong>4 à 6 jours</strong> après le début du traitement, sans fièvre, est transitoire et cède rapidement à l'arrêt de l'antibiotique. Aucune exploration n'est nécessaire.</p>"},{"i":"7ce9171300fd","n":286,"o":"286-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","q":"Quels sont les deux mécanismes principaux de la diarrhée des antibiotiques ?","a":"<ul><li>L'<strong>effet pharmacologique sur la motricité</strong> intestinale (rare), avec des antibiotiques comme l'<strong>érythromycine</strong> et l'<strong>acide clavulanique</strong>.</li><li>La <strong>modification de la flore intestinale</strong> (fréquent), conduisant à une <strong>dysbiose</strong>.</li></ul>"},{"i":"a623c3cdbb0b","n":286,"o":"286-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","q":"Quelles sont les caractéristiques principales de la colite infectieuse liée aux antibiotiques ?","a":"<p>Elle est <strong>rare</strong>, principalement due à <em><strong>Clostridium difficile</strong></em> ou <em><strong>Klebsiella oxytoca</strong></em>. Elle peut apparaître quelques jours après la prise. Dans le cas de <em>K. oxytoca</em>, elle peut se manifester par une <strong>diarrhée hémorragique</strong>, des lésions segmentaires et un aspect ischémique. Elle nécessite une coproculture orientée et une recherche de toxines de <em>C. difficile</em>.</p>"},{"i":"c22c30e02473","n":286,"o":"286-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","q":"Quelle est la définition d'une diarrhée des antibiotiques ?","a":"<p>Une diarrhée des antibiotiques est une modification du transit intestinal qui survient pendant un traitement antibiotique ou dans les <strong>2 mois</strong> suivant son arrêt.</p>"},{"i":"de2ad39f2cba","n":286,"o":"286-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la diarrhée des antibiotiques et ses deux catégories","q":"Quelles sont les deux catégories de diarrhée des antibiotiques résultant d'une modification de la flore intestinale ?","a":"<ul><li>La <strong>diarrhée bénigne fonctionnelle</strong>.</li><li>La <strong>colite infectieuse</strong>.</li></ul>"},{"i":"0fda2d2752b1","n":286,"o":"286-7","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires","q":"Quels terrains ou contextes favorisent la réalisation d'examens complémentaires en cas de diarrhée aiguë ?","a":"<p>Les examens complémentaires pour une diarrhée aiguë sont favorisés par les terrains et contextes suivants :</p><ul><li><strong>Terrain</strong> : <strong>sujet âgé</strong>, <strong>valvulopathie</strong>, <strong>immunodépression</strong>.</li><li><strong>Contexte</strong> : <strong>contexte épidémique nosocomial</strong>, <strong>diarrhée post-antibiotique</strong> (sauf forme bénigne), <strong>suspicion de TIAC</strong> (Toxi-Infection Alimentaire Collective).</li></ul>"},{"i":"94ff1e1a72b9","n":286,"o":"286-7","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires","q":"Quand n'est-il pas nécessaire de réaliser une exploration complémentaire pour une diarrhée aiguë ?","a":"<p>Aucune exploration n'est nécessaire devant une <strong>diarrhée aiguë banale</strong>, c'est-à-dire sans fièvre, sans signe de gravité, et évoluant rapidement vers la guérison. C'est le cas de la majorité des diarrhées aiguës.</p>"},{"i":"e2d28d2f80cf","n":286,"o":"286-7","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires","q":"Dans quel contexte clinique général des examens complémentaires sont-ils indiqués face à une diarrhée aiguë ?","a":"<p>Des examens complémentaires sont indiqués en présence d'au moins un des critères suivants :</p><ul><li><strong>Terrain</strong> : sujet âgé, valvulopathie, immunodépression.</li><li><strong>Clinique</strong> : évolution > 3 jours, fièvre > 38,5°C, syndrome dysentérique (présence de sang ou de pus dans les selles), déshydratation.</li><li><strong>Contexte</strong> : épidémie nosocomiale, diarrhée post-antibiotique (sauf forme bénigne), suspicion de TIAC (Toxi-Infection Alimentaire Collective).</li></ul>"},{"i":"eca0cdc6bdcc","n":286,"o":"286-7","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires","q":"Devant quels signes cliniques spécifiques une exploration complémentaire de diarrhée aiguë est-elle nécessaire ?","a":"<p>Une exploration complémentaire est nécessaire si la diarrhée aiguë présente :</p><ul><li>Une <strong>évolution > 3 jours</strong>.</li><li>Une <strong>fièvre > 38,5°C</strong>.</li><li>Un <strong>syndrome dysentérique</strong> (présence de sang ou de pus dans les selles).</li><li>Une <strong>déshydratation</strong>.</li></ul>"},{"i":"67a88103a34b","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quel germe bactérien présente des mécanismes variables (entéro-toxinogène, entéro- pathogène, entéro-invasif ou entéro-hémorragique) dans les intoxications alimentaires, pouvant entraîner des syndromes cholériformes, gastro-entéritiques ou dysentériques ?","a":"<p>Il s'agit d'<strong><em>Escherichia coli</em></strong>.</p>"},{"i":"949c87e629a6","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quelle physiopathologie bactérienne est typiquement associée à un tableau gastro-entéritique ou dysentérique dans les intoxications alimentaires ?","a":"<p>Un tableau gastro-entéritique ou dysentérique est schématiquement associé aux germes <strong>entéro-invasifs</strong>.</p>"},{"i":"a65a35993b5b","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quels germes bactériens entéro-invasifs sont fréquemment en cause dans une intoxication alimentaire présentant un tableau gastro-entéritique ?","a":"<p>Il s'agit de <strong>Salmonella</strong> (non Typhi), <strong>Campylobacter</strong> et <strong>Yersinia</strong>.</p>"},{"i":"d5f5090fe793","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quel germe bactérien toxinogène est responsable d'une intoxication alimentaire cholériforme, due à une toxine pré-formée dans l'aliment ?","a":"<p>Il s'agit du <strong>Staphylocoque doré</strong> (<em>S. aureus</em>).</p>"},{"i":"e1439f4532f9","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quelle physiopathologie bactérienne est typiquement associée à une diarrhée cholériforme ou sécrétoire dans les intoxications alimentaires ?","a":"<p>Une diarrhée cholériforme ou sécrétoire est schématiquement associée aux germes <strong>toxinogènes</strong>.</p>"},{"i":"e731e02974c3","n":286,"o":"286-8","u":"Étiologie","t":"Connaître les principaux germes en cause dans les intoxications alimentaires (Staphylocoque doré, Clostridium perfringens, Salmonella, Campylobacter, Escherichia coli, Yersinia)","q":"Quel germe bactérien toxinogène peut causer une intoxication alimentaire avec un syndrome cholériforme ?","a":"<p>Il s'agit de <strong><em>Clostridium perfringens</em></strong>.</p>"},{"i":"033a97c3a1de","n":286,"o":"286-9","u":"Suivi et/ou Pronostic","t":"Connaître la complication majeure : la déshydratation globale (et ses conséquences)","q":"Quelles sont les spécificités du pronostic et de la mortalité liées à la déshydratation chez le sujet âgé de plus de 75 ans lors d'une diarrhée aiguë ?","a":"<p>Chez le sujet de <strong>plus de 75 ans</strong>, la mortalité est principalement due aux <strong>accidents de déshydratation</strong> et à l'<strong>hypoperfusion des organes vitaux</strong>. Un pic de mortalité est souvent observé <strong>8 à 10 jours après le début de la diarrhée</strong>, même si celle-ci a déjà disparu.</p>"},{"i":"2ae45598cfa5","n":286,"o":"286-9","u":"Suivi et/ou Pronostic","t":"Connaître la complication majeure : la déshydratation globale (et ses conséquences)","q":"Quels sont les éléments perdus lors d'une diarrhée aiguë et participant à la déshydratation ?","a":"<p>Les diarrhées aiguës entraînent des pertes importantes :</p><ul><li>d'<strong>eau</strong></li><li>de <strong>sodium</strong></li><li>de <strong>potassium</strong></li><li>de <strong>bicarbonates</strong></li></ul>"},{"i":"b7a9e2034d3c","n":286,"o":"286-9","u":"Suivi et/ou Pronostic","t":"Connaître la complication majeure : la déshydratation globale (et ses conséquences)","q":"Quels sont les signes cliniques distinctifs de la déshydratation intra-cellulaire et de la déshydratation extracellulaire lors d'une diarrhée aiguë ?","a":"<ul><li>Les signes de la déshydratation <strong>intra-cellulaire</strong> incluent la <strong>soif</strong>, la <strong>sécheresse des muqueuses</strong>, la <strong>fièvre</strong>, les <strong>troubles de conscience</strong>, les <strong>cernes</strong> et les <strong>yeux creusés</strong>.</li><li>Les signes de la déshydratation <strong>extracellulaire</strong> incluent la <strong>tachycardie</strong>, l'<strong>hypotension</strong>, et l'<strong>oligurie</strong> qui sont des <strong>signes de gravité</strong>, ainsi que le <strong>pli cutané persistant</strong>.</li></ul>"},{"i":"cf747647780c","n":286,"o":"286-9","u":"Suivi et/ou Pronostic","t":"Connaître la complication majeure : la déshydratation globale (et ses conséquences)","q":"Quelle est la complication majeure de la diarrhée aiguë chez l'enfant et l'adulte, et quels compartiments touche-t-elle ?","a":"<p>La complication majeure de la diarrhée aiguë est la <strong>déshydratation globale</strong>, touchant les compartiments <strong>intra-cellulaire et extra-cellulaire</strong>.</p>"}]};